/**
 * HGhub Rex/Forward 模块图标 · Cloudflare Worker
 * /anime.png 动漫聚合   /vod.png 影视聚合
 */
const ICONS = {
  "/anime.png": "",
  "/vod.png": "",
};
export default {
  async fetch(request) {
    const p = new URL(request.url).pathname;
    const b = ICONS[p];
    if (!b) return new Response("not found", { status: 404 });
    const bin = Uint8Array.from(atob(b), (c) => c.charCodeAt(0));
    return new Response(bin, { headers: { "Content-Type": "image/png", "Cache-Control": "public, max-age=86400", "Access-Control-Allow-Origin": "*" } });
  },
};
